// Compute daily provider usage summary from Redis metric counters
const metrics = $input.first().json.metrics || {};
const today = new Date();
today.setUTCDate(today.getUTCDate() - 1);
const dateStr = today.toISOString().split('T')[0];

// Helper to read counter with default 0
const m = (key) => parseInt(metrics[key] || '0', 10);
const mf = (key) => parseFloat(metrics[key] || '0');

const openaiCalls   = m('assessment.openai.calls')   + m('assessment.student.completed') + m('assessment.professor.completed');
const openaiTokens  = m('assessment.openai.tokens')  || 0;
const openaiCost    = mf('assessment.openai.cost_usd') || 0;

const claudeCalls   = openaiCalls; // Claude always mirrors OpenAI (1:1)
const claudeTokens  = m('assessment.claude.tokens')  || 0;
const claudeCost    = mf('assessment.claude.cost_usd') || 0;

const geminiCalls   = m('assessment.gemini.calls')   || 0;
const geminiTokens  = m('assessment.gemini.tokens')  || 0;
const geminiCost    = mf('assessment.gemini.cost_usd') || 0;

const studentCompleted  = m('assessment.student.completed');
const professorCompleted = m('assessment.professor.completed');
const escalations       = m('assessment.escalations.created');
const duplicates        = m('assessment.student.duplicate') + m('assessment.professor.duplicate');
const totalCost         = openaiCost + claudeCost + geminiCost;

return [{ json: {
  date_utc:            dateStr,
  openai_calls:        openaiCalls,
  openai_tokens:       openaiTokens,
  openai_cost_usd:     openaiCost,
  claude_calls:        claudeCalls,
  claude_tokens:       claudeTokens,
  claude_cost_usd:     claudeCost,
  gemini_calls:        geminiCalls,
  gemini_tokens:       geminiTokens,
  gemini_cost_usd:     geminiCost,
  total_cost_usd:      totalCost,
  student_completed:   studentCompleted,
  professor_completed: professorCompleted,
  escalations_created: escalations,
  duplicates_rejected: duplicates,
  raw_metrics:         metrics,
} }];

// Log the daily summary as a structured audit event
// In production: POST to /internal/assessment/usage-summary (future endpoint)
// or write directly to Supabase assessment_daily_usage table.
const summary = $node['Compute Daily Summary'].json;
console.log(JSON.stringify({
  level: 'info',
  event: 'assessment_audit.daily_usage',
  ...summary,
}));

// Check if cost exceeds budget threshold (configurable)
const DAILY_BUDGET_USD = parseFloat($env['ASSESSMENT_DAILY_BUDGET_USD'] || '50');
const over_budget = summary.total_cost_usd > DAILY_BUDGET_USD;
if (over_budget) {
  console.error(JSON.stringify({
    level: 'error',
    event: 'assessment_audit.budget_exceeded',
    total_cost_usd: summary.total_cost_usd,
    budget_usd: DAILY_BUDGET_USD,
    date_utc: summary.date_utc,
  }));
}

return [{ json: { ...summary, over_budget, budget_usd: DAILY_BUDGET_USD } }];

// Audit complete — log final summary
const s = $node['Log and Check Budget'].json;
console.log(JSON.stringify({
  level: 'info',
  event: 'assessment_audit.complete',
  date_utc: s.date_utc,
  total_cost_usd: s.total_cost_usd,
  student_completed: s.student_completed,
  professor_completed: s.professor_completed,
  escalations_created: s.escalations_created,
}));
return [{ json: { ok: true, date_utc: s.date_utc } }];
